class PackedTermBindingContractTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI P = VF.createIRI("urn:mask:predicate");

	@Test
	void valuedTupleParameterRemainsAnAssuredOutputInTheProviderView() {
		StatementPattern source = pattern(Var.of("parameter", P, false, false));
		PackedQuery query = PackedQueryCodec.encode(source);
		PackedQueryView view = new PackedQueryView(query);
		assertThat(view.outputBindingNames(query.rootRelId())).containsExactlyInAnyOrder("s", "parameter", "o");
		assertThat(query.bindingNames(query.relAssuredMaskId(query.rootRelId())))
				.containsExactlyInAnyOrder("s", "parameter", "o");
		assertThat(view.bindingNames(view.materializeRelation(query.rootRelId())))
				.containsExactlyInAnyOrder("s", "parameter", "o");
		assertThat(view.bindingNames(source.clone())).containsExactlyInAnyOrder("s", "parameter", "o");
	}

	@ParameterizedTest
	@CsvSource({ "true,true,false", "true,false,true", "false,false,true", "false,true,true" })
	void tuplePrefixChecksRespectValueAndConstantRoles(boolean valued, boolean constant, boolean observes) {
		QueryBindingSet input = new QueryBindingSet();
		input.addBinding("parameter", P);
		BindingSetAssignment prefix = new BindingSetAssignment();
		prefix.setBindingSets(List.of(input));
		prefix.setDeclaredBindingNames(Set.of("parameter"));
		PackedQuery query = PackedQueryCodec.encode(new Join(prefix,
				pattern(Var.of("parameter", valued ? P : null, false, constant))));
		int left = query.relChild(query.rootRelId(), 0);
		int right = query.relChild(query.rootRelId(), 1);
		PackedQueryView view = new PackedQueryView(query);
		PackedCostContext context = new PackedCostContext();
		context.reset(new int[] { left }, 0, 1, 1.0d);
		assertThat(view.prefixBindsStatementComponent(context, right, 1)).isEqualTo(observes);
		assertThat(view.relationBindsStatementComponent(left, right, 1)).isEqualTo(observes);
		assertThat(view.relationAssuresStatementComponent(left, right, 1)).isEqualTo(observes);
		assertThat(view.outputBindingNames(right).contains("parameter")).isEqualTo(!constant);
	}

	@Test
	void explicitAliasTargetSurvivesAConstantWithTheSameNameInItsArgument() {
		StatementPattern pattern = pattern(Var.of("target", P, true, true));
		Projection projection = new Projection(pattern, new ProjectionElemList(new ProjectionElem("s", "target")));
		PackedQuery query = PackedQueryCodec.encode(projection.clone());
		PackedQueryView view = new PackedQueryView(query);
		assertThat(view.bindingNames(projection)).containsExactly("target");
		assertThat(view.bindingNames(view.materializeRelation(query.rootRelId()))).containsExactly("target");
		assertThat(view.outputBindingNames(query.rootRelId())).containsExactly("target");
	}

	@Test
	void declaredProviderSchemaPreservesDirectExistsNamesForCapturedAndDetachedTrees() {
		Filter filter = new Filter(new org.eclipse.rdf4j.query.algebra.SingletonSet(),
				new org.eclipse.rdf4j.query.algebra.Exists(new StatementPattern(Var.of("innerSubject"),
						Var.of("fixed", P, true, true), Var.of("innerObject"))));
		PackedQuery query = PackedQueryCodec.encode(filter.clone());
		PackedQueryView view = new PackedQueryView(query);
		assertThat(view.bindingNames(filter)).containsExactlyInAnyOrder("innerSubject", "innerObject");
		assertThat(view.bindingNames(view.materializeRelation(query.rootRelId())))
				.containsExactlyInAnyOrder("innerSubject", "innerObject");
		assertThat(view.outputBindingNames(query.rootRelId())).isEmpty();
	}

	@Test
	void declaredProviderSchemaIntersectsNamesAtAnIntersection() {
		TupleExpr intersection = new org.eclipse.rdf4j.query.algebra.Intersection(
				new StatementPattern(Var.of("shared"), Var.of("leftP", P, true, true), Var.of("leftOnly")),
				new StatementPattern(Var.of("shared"), Var.of("rightP", P, true, true), Var.of("rightOnly")));
		PackedQuery query = PackedQueryCodec.encode(intersection.clone());
		PackedQueryView view = new PackedQueryView(query);
		assertThat(view.bindingNames(intersection)).containsExactly("shared");
		assertThat(view.bindingNames(view.materializeRelation(query.rootRelId()))).containsExactly("shared");
	}

	@Test
	void declaredProviderSchemaRetainsAssuredPathBodyNames() {
		TupleExpr path = new org.eclipse.rdf4j.query.algebra.ArbitraryLengthPath(
				Var.of("start"), new StatementPattern(Var.of("bodyStart"),
						Var.of("fixed", P, true, true), Var.of("bodyEnd")),
				Var.of("end"), 1L);
		PackedQuery query = PackedQueryCodec.encode(path.clone());
		PackedQueryView view = new PackedQueryView(query);
		assertThat(view.bindingNames(path)).containsExactlyInAnyOrder("start", "end", "bodyStart", "bodyEnd");
		assertThat(view.bindingNames(view.materializeRelation(query.rootRelId())))
				.containsExactlyInAnyOrder("start", "end", "bodyStart", "bodyEnd");
	}

	@ParameterizedTest
	@CsvSource({ "all,all,1", "retained,retained,1", "all,retained,2" })
	void contextualCostIdentityIncludesTheCompleteExplicitConditionScope(String firstMode, String secondMode,
			int expectedCalls) {
		Filter first = filter(firstMode, false);
		Filter second = filter(secondMode, true);
		PackedQuery query = PackedQueryCodec.encodeForPlanning(new Union(first, second));
		int[] ids = new int[2];
		int count = 0;
		for (int id = 1; id <= query.relationCount(); id++) {
			if (query.relOperator(id) == PackedRelOp.FILTER) {
				ids[count++] = id;
			}
		}
		assertThat(count).isEqualTo(2);
		int[] calls = new int[1];
		PackedCostSession provider = new PackedCostSession() {
			@Override
			public void estimateLeaf(int id, PackedCostContext context, PackedCostEstimate output) {
				throw new AssertionError("only condition transform costs are requested");
			}

			@Override
			public void appendFactor(int id, PackedCostContext context, PackedCostEstimate output) {
				throw new AssertionError("only condition transform costs are requested");
			}

			@Override
			public void refineOperator(int id, PackedCostContext context, PackedCostEstimate output) {
				output.setRows(3.0d, 9.0d);
				output.setEvidenceStateId(++calls[0]);
			}
		};
		EventSourcingPackedCostSession session = new EventSourcingPackedCostSession(provider, query);
		PackedCostContext context = new PackedCostContext();
		context.reset(new int[0], 0, 0, 1.0d, 7);
		PackedCostEstimate firstCost = new PackedCostEstimate();
		PackedCostEstimate secondCost = new PackedCostEstimate();
		firstCost.setRows(3.0d, 9.0d);
		secondCost.setRows(3.0d, 9.0d);
		session.refineOperator(ids[0], context, firstCost);
		session.refineOperator(ids[1], context, secondCost);
		assertThat(calls[0]).isEqualTo(expectedCalls);
		assertThat(firstCost.costEventId() == secondCost.costEventId()).isEqualTo(expectedCalls == 1);
	}

	private static Filter filter(String mode, boolean detailed) {
		TupleExpr input = pattern(Var.of("constant", P, true, true));
		if (detailed) {
			input = new Join(input, new StatementPattern(Var.of("s"),
					Var.of("otherConstant", P, true, true), Var.of("detail")));
		}
		Filter filter = new Filter(input, new Bound(Var.of("o")));
		filter.setConditionBindingScope(mode.equals("all") ? ConditionBindingScope.ALL
				: ConditionBindingScope.retain(Set.of("o")));
		return filter;
	}

	private static StatementPattern pattern(Var predicate) {
		return new StatementPattern(Var.of("s"), predicate, Var.of("o"));
	}
}
